document.addEventListener("DOMContentLoaded",()=>{const amountInput=document.getElementById('amount');const daysRange=document.getElementById('daysValue');const daysValue=document.getElementById('day');const resultBox=document.getElementById('prof');daysRange.addEventListener('input',()=>{daysValue.textContent=daysRange.value});function animateValue(element,start,end,duration){let startTimestamp=null;const step=(timestamp)=>{if(!startTimestamp)startTimestamp=timestamp;const progress=Math.min((timestamp-startTimestamp)/duration,1);const value=Math.floor(progress*(end-start)+start);element.textContent="€"+value;if(progress<1){requestAnimationFrame(step)}};requestAnimationFrame(step)}
function calculate(){let amount=Number(amountInput.value);let days=Number(daysRange.value);const min=Number(amountInput.min);const max=Number(amountInput.max);if(amount<min)amount=min;if(amount>max)amount=max;const total=amount*days;let start=resultBox.dataset.value?Number(resultBox.dataset.value):0;animateValue(resultBox,start,total,500);resultBox.dataset.value=total}
calculate();document.addEventListener('click',(e)=>{if(e.target===amountInput||e.target===daysRange)return;calculate()});daysRange.addEventListener('input',()=>{calculate()});if(window.innerWidth<767){var slider=tns({container:".partners-slider",items:1.3,slideBy:1,mouseDrag:!0,autoplay:!0,controls:!1,nav:!1,autoplayButtonOutput:!1,gutter:16,});var slider1=tns({container:".opportunities-slider",items:1.5,slideBy:1,mouseDrag:!0,autoplay:!0,controls:!1,nav:!1,autoplayButtonOutput:!1,gutter:16,});var slider2=tns({container:".benefits-slider",items:1.2,slideBy:1,mouseDrag:!0,autoplay:!0,controls:!1,nav:!1,autoplayButtonOutput:!1,});var slider3=tns({container:".cards-row.slider4",items:1.3,slideBy:1,mouseDrag:!0,autoplay:!0,controls:!1,nav:!1,autoplayButtonOutput:!1,})}})